#include <stdio.h>
#include <ctype.h>

int main(void) {
    long lines = 0, words = 0, chars = 0;
    int c;
    int in_word = 0; // flag indicating we are inside a word

    while ((c = getc(stdin)) != EOF) {
        chars++;
        if (c == '\n')
            lines++;
        if (isspace((unsigned char)c)) {
            // whitespace ends a word
            in_word = 0;
        } else {
            // non‑whitespace starts a new word if we were not already in one
            if (!in_word) {
                words++;
                in_word = 1;
            }
        }
    }

    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
